# ------------------------------------------------------------

println("\n--- CONGRUENCE ---")
res = CC.chaincongruence(W, Delta_0, Delta_1; epsilon=1e-6)
println(CC.congruence_report(res))

# ------------------------------------------------------------
# 6. EXTRACT LOCAL BLOCKS
# IMPORTANT:
# blocks[i] is generated automatically here.
# You do NOT type blocks[i] by hand.
# ------------------------------------------------------------

println("\n--- EXTRACT BLOCKS ---")
blocks = BB.extract_blocks(W, Delta_0, Delta_1;
    nverts = nverts,
    nedges = nedges,
    nfaces = nfaces)

println("number of blocks = ", length(blocks))

# ------------------------------------------------------------
# 7. CHECK EACH BLOCK BOUNDARY INTERNALLY
# ------------------------------------------------------------

println("\n--- BLOCK BOUNDARIES ---")
summary = BB.summarize_block_boundaries(blocks)
println(BB.boundary_report(summary))

# ------------------------------------------------------------
# 8. CHECK PAIRS OF BLOCKS ALONG ORIGINAL EDGES
