# original faces / local blocks to compare.
# ------------------------------------------------------------

println("\n--- BLOCK PAIR CONGRUENCE ---")
pairsummary = BPC.validate_all_original_edges(blocks, FE_orig, lar; atol=1e-7)
println(BPC.pair_congruence_report(pairsummary))

println("\n--- REPAIR ALL ORIGINAL EDGES ---")
repsummary = BPC.repair_all_original_edges(blocks, FE_orig, lar; atol=1e-7)
println(BPC.repair_report(repsummary))

println("\n--- REASSEMBLE REPAIRED BLOCKS ---")
repaired = BPC.assemble_repaired_blocks(repsummary.blocks)

println("size(repaired.W) = ", size(repaired.W))
println("size(repaired.Delta_0) = ", size(repaired.Delta_0))
println("size(repaired.Delta_1) = ", size(repaired.Delta_1))

println("\n--- CONGRUENCE AFTER REPAIR ---")
res2 = CC.chaincongruence(repaired.W, repaired.Delta_0, repaired.Delta_1; epsilon=1e-6)
println(CC.congruence_report(res2))

println("\n--- GLOBAL 2-SKELETON VALIDATION AFTER REPAIR ---")
rep2 = V2.validate_2skeleton(res2.V, res2.EV, res2.FE)
@show rep2.stage
@show rep2.ok
@show rep2.balance
@show rep2.manifold

# ------------------------------------------------------------
# 9. GLOBAL 2-SKELETON VALIDATION
# ------------------------------------------------------------

println("\n--- GLOBAL 2-SKELETON VALIDATION ---")
rep = V2.validate_2skeleton(res.V, res.EV, res.FE)

@show rep.stage
@show rep.ok
@show rep.balance
@show rep.manifold

# ------------------------------------------------------------
# 10. DIAGNOSTICS FOR GLOBAL BALANCE FAILURE
# ------------------------------------------------------------

if rep.stage == :balance && rep.balance !== nothing
    println("\n--- BAD GLOBAL EDGES (BALANCE FAILURE) ---")
    badrows = rep.balance.odd_rows
    println("odd_rows = ", badrows)

    for e in badrows
        println("edge ", e, " => ", res.EV[e])
        println("incident faces = ", [k for (k, face) in enumerate(res.FE) if e in face])
    end
end



